            aOrbiterK = (aWandererA + RotL64(aCross, 3U)) + 0x610E9B29F7234D2FULL;
            aOrbiterG = (((aWandererJ + RotL64(aPrevious, 57U)) + RotL64(aCarry, 19U)) + 0x4AE0EE6A161E65E5ULL) + aOASaltE[(((511U - aIndex) + 349U)) & S_SALT1];
            aOrbiterJ = ((aWandererB + RotL64(aScatter, 51U)) + RotL64(aCarry, 41U)) + 0x4B1E9DF9BD82E28BULL;
            aOrbiterD = ((aWandererH + RotL64(aIngress, 13U)) + 0x8595F4CCCD9E659EULL) + aOASaltH[(((511U - aIndex) + 408U)) & S_SALT1];
            aOrbiterB = (((aWandererF + RotL64(aCross, 37U)) + RotL64(aCarry, 57U)) + 0xECA2502E2F1D89B8ULL) + aOASaltC[((aIndex + 178U)) & S_SALT1];
            aOrbiterA = ((aWandererI + RotL64(aScatter, 30U)) + 0xF78FB912586E439BULL) + aOASaltF[((aIndex + 324U)) & S_SALT1];
            aOrbiterH = ((aWandererD + RotL64(aIngress, 43U)) + 0xBB17874A921D4A13ULL) + aOASaltB[((aIndex + 11U)) & S_SALT1];
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0xF65FD23241E9A615ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x13479CE064A82E6FULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xFA2654DC15F06D23ULL), 57U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0xAB2F1741A3887E7DULL;
