            aOrbiterB = RotL64((aOrbiterB * 0x2A626B2B822DC65DULL), 35U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterA) + 0x918FA8E44EAE1310ULL) + aOUSaltB[(((511U - aIndex) + 79U)) & S_SALT1];
