            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0xA3EF072577D10EB4ULL) + aOUSaltE[((aIndex + 143U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterH) ^ 0x41B22AE503AB0420ULL) ^ aOUSaltD[((aIndex + 330U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x5C99B310630BAE6FULL), 51U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x608FAE3E20C76F42ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0xC7CCA042F2C3FAAFULL;
            aOrbiterA = RotL64((aOrbiterA * 0xB890E6A3E9250AE1ULL), 13U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x55C42069DDBB5F70ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0xC0ABB12D4DB31413ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xA4429DBE96AF3B79ULL), 5U);
            //
            aIngress = RotL64(aOrbiterD, 4U) ^ aOrbiterJ;
            aIngress = aIngress + (RotL64(aOrbiterH, 37U) ^ aOrbiterB);
            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterK, 13U));
            aIngress = aIngress + RotL64(aOrbiterG, 19U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererH = aWandererH ^ (((RotL64(aScatter, 57U) + RotL64(aOrbiterK, 19U)) + aOrbiterH) + aWUSaltE[(((511U - aIndex) + 486U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aIngress, 51U) + RotL64(aOrbiterA, 57U)) + aOrbiterH) + RotL64(aCarry, 43U));
