            aIngress = (RotL64(aFuseLaneA[((aIndex + 15447U)) & S_BLOCK1], 43U) ^ RotL64(aWindLaneC[((aIndex + 14708U)) & S_BLOCK1], 14U));
            aIngress ^= (RotL64(aWoodLaneB[((aIndex + 14608U)) & S_BLOCK1], 51U) ^ RotL64(aMagmaLaneC[((aIndex + 10941U)) & S_BLOCK1], 27U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 8595U)) & S_BLOCK1], 12U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 10458U)) & S_BLOCK1], 29U));
            aCross ^= (RotL64(aPlasmaLaneC[((S_BLOCK1 - aIndex + 11861U)) & S_BLOCK1], 57U) ^ RotL64(aWaterLaneB[((aIndex + 9022U)) & S_BLOCK1], 3U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 10U) ^ RotL64(aCarry, 51U)) + (RotL64(aPrevious, 23U) ^ RotL64(aCross, 37U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterC = (aWandererE + RotL64(aScatter, 29U)) + 0x03A867A05914A981ULL;
            aOrbiterJ = (((aWandererD + RotL64(aIngress, 13U)) + RotL64(aCarry, 39U)) + 0xC11AB4132D7B2321ULL) + aOASaltB[((aIndex + 290U)) & S_SALT1];
            aOrbiterA = (aWandererI + RotL64(aPrevious, 47U)) + 0x83EBCED736AB418FULL;
            aOrbiterD = (aWandererK + RotL64(aCross, 19U)) + 0xAA95F2105C9A122AULL;
            aOrbiterE = (((aWandererG + RotL64(aPrevious, 60U)) + RotL64(aCarry, 53U)) + 0x7B76A50683B1CF7CULL) + aOASaltF[((aIndex + 129U)) & S_SALT1];
            aOrbiterK = ((aWandererH + RotL64(aCross, 53U)) + RotL64(aCarry, 21U)) + 0xF9CD12BD0A259A9AULL;
            aOrbiterG = ((aWandererA + RotL64(aScatter, 3U)) + 0xED77E68F3734B018ULL) + aOASaltC[(((511U - aIndex) + 60U)) & S_SALT1];
            //
            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0xC45C308ED069C501ULL) + aOUSaltD[(((511U - aIndex) + 45U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0x99289B5AB4352B50ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x17DC2B9C50D8ED89ULL), 19U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x6F0856B71198B08FULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x0E1AAADF2AE0D036ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1505D6C19281BAEDULL), 27U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0xBECF34E3ABF8FCA4ULL) + aOUSaltG[(((511U - aIndex) + 139U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterK) ^ 0xAFCD03539F666EDCULL) ^ aOUSaltB[((aIndex + 467U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x5684D0D758347D51ULL), 57U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterE) + 0x856C80A8C67CFAC8ULL) + aOUSaltE[(((511U - aIndex) + 406U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0x1D4E11AC98EDE249ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x5ECA1316DE76131FULL), 3U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0x1E165BA636637033ULL) + aOUSaltA[(((511U - aIndex) + 297U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0xA889632E13CF4E68ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x2D994EE0702B4A57ULL), 35U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x41F7C094E0BF29EEULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0xAE7493D395A20992ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x6A45B0C8C8FAFDC3ULL), 47U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterK) + 0xBE227E12F7918F51ULL) + aOUSaltC[(((511U - aIndex) + 411U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x96F69409D9460A68ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x9E96BA79533514D5ULL), 11U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterC, 58U);
            aIngress = aIngress + (RotL64(aOrbiterG, 29U) ^ aOrbiterD);
            aIngress = aIngress + (RotL64(aOrbiterJ, 13U) ^ aOrbiterE);
            aIngress = aIngress + RotL64(aOrbiterK, 19U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererI = aWandererI + (((RotL64(aPrevious, 26U) + aOrbiterA) + RotL64(aOrbiterD, 29U)) + RotL64(aCarry, 5U));
            aWandererA = aWandererA ^ (((RotL64(aCross, 37U) + aOrbiterK) + RotL64(aOrbiterD, 6U)) + aWUSaltG[(((511U - aIndex) + 407U)) & S_SALT1]);
            aWandererD = aWandererD + (((RotL64(aIngress, 43U) + aOrbiterJ) + RotL64(aOrbiterE, 57U)) + aWUSaltC[(((511U - aIndex) + 73U)) & S_SALT1]);
            aWandererG = aWandererG ^ (((RotL64(aScatter, 51U) + aOrbiterC) + RotL64(aOrbiterK, 51U)) + aWUSaltF[((aIndex + 202U)) & S_SALT1]);
            aWandererK = aWandererK + ((((RotL64(aIngress, 3U) + RotL64(aOrbiterC, 43U)) + aOrbiterJ) + RotL64(aCarry, 23U)) + aWUSaltB[((aIndex + 298U)) & S_SALT1]);
            aWandererE = aWandererE ^ (((RotL64(aScatter, 19U) + aOrbiterG) + RotL64(aOrbiterE, 35U)) + aWUSaltH[((aIndex + 480U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aPrevious, 11U) + aOrbiterJ) + RotL64(aOrbiterA, 13U));
